import { test, expect } from '@playwright/test';

test.describe('Search Results Debouncing', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should debounce search API calls and update results as user types', async ({ page }) => {
    // Setup API interception for search
    await page.route('**/api/search*', (route) => {
      route.continue();
    });

    // Get search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Type first character
    await searchInput.fill('a');

    // Wait for debounce period (300ms)
    await page.waitForTimeout(350);

    // Verify API was called with first character
    const searchApiCall = page.route('**/api/search*', (route) => {
      route.continue();
    });
    await expect(searchApiCall).toBeCalledWith('a');

    // Verify results container is empty initially
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();
    const resultItems = page.getByRole('listitem');
    await expect(resultItems).toHaveCount(0);

    // Type second character
    await searchInput.fill('apple');

    // Wait for debounce period
    await page.waitForTimeout(350);

    // Verify API was called with full string
    await expect(searchApiCall).toBeCalledWith('apple');

    // Verify results are displayed
    await expect(resultItems).toHaveCount(1);
    const resultText = page.getByText('Apple');
    await expect(resultText).toBeVisible();

    // Clear input and verify API is not called
    await searchInput.clear();
    await page.waitForTimeout(350);

    // Verify API was not called with empty string
    await expect(searchApiCall).not.toBeCalledWith('');
  });

  test('should handle rapid typing and only call API with final value', async ({ page }) => {
    // Setup API interception
    await page.route('**/api/search*', (route) => {
      route.continue();
    });

    // Get search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Rapidly type multiple characters
    await searchInput.fill('banana');

    // Wait for debounce period
    await page.waitForTimeout(350);

    // Verify API was called only once with the final value
    const searchApiCall = page.route('**/api/search*', (route) => {
      route.continue();
    });
    await expect(searchApiCall).toBeCalledWith('banana');

    // Verify results are displayed
    const resultItems = page.getByRole('listitem');
    await expect(resultItems).toHaveCount(1);
    const resultText = page.getByText('Banana');
    await expect(resultText).toBeVisible();

    // Verify debounce timer is reset on subsequent input
    await searchInput.clear();
    await searchInput.fill('b');
    await page.waitForTimeout(350);

    // Verify API was called again with the new value
    await expect(searchApiCall).toBeCalledWith('b');
  });
});
